(function() {
    // ============ 横屏锁（仅横屏内容生效） ============
    var st = document.createElement('style');
    st.textContent = 'body.fs-ls{transform:rotate(90deg) translateY(-100%);transform-origin:top left;width:100vh;height:100vw!important;overflow:hidden!important;position:fixed!important;top:0!important;left:0!important}';
    document.head.appendChild(st);

    function isLS() {
        var v = document.querySelector('video');
        return (!v || !v.videoWidth) ? true : v.videoWidth >= v.videoHeight;
    }
    function fsHandler() {
        var full = document.fullscreenElement || document.webkitFullscreenElement;
        if (full && isLS()) {
            document.body.classList.add('fs-ls');
            if (screen.orientation && screen.orientation.lock)
                screen.orientation.lock('landscape').catch(function(){});
        } else {
            document.body.classList.remove('fs-ls');
            if (screen.orientation && screen.orientation.unlock)
                screen.orientation.unlock();
        }
    }
    document.addEventListener('fullscreenchange', fsHandler);
    document.addEventListener('webkitfullscreenchange', fsHandler);
    if (document.fullscreenElement || document.webkitFullscreenElement) fsHandler();

    // ============ 手势 ============
    function bind(v) {
        // ★ 可调参数
        var LONG_PRESS_MS = 500;     // 长按多少毫秒触发加速
        var FAST_RATE     = 3.0;     // 加速倍率
        var SWIPE_SENS    = 1.0;     // 滑动灵敏度：1=全屏宽跳完整个视频；0.5=半屏；2=两屏
        var SEEK_THROTTLE = 24;      // 拖动节流(ms)

        var sx = 0, st0 = 0, lp = null, ff = false, wasPaused = false;
        var pendT = 0, seekTimer = null, seekPending = false, tipEl = null;

        function fmt(t){var m=Math.floor(t/60),s=Math.floor(t%60);return(m<10?'0':'')+m+':'+(s<10?'0':'')+s;}
        function showTip(t){
            if(!tipEl){tipEl=document.createElement('div');tipEl.style.cssText='position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);background:rgba(0,0,0,.75);color:#fff;padding:10px 20px;border-radius:8px;font-size:16px;font-weight:bold;z-index:99999;pointer-events:none;';document.body.appendChild(tipEl);}
            tipEl.textContent = fmt(t)+' / '+fmt(v.duration||0);
            tipEl.style.display = 'block';
        }
        function hideTip(){ if(tipEl) tipEl.style.display='none'; }

        function stopLong(){ if(lp){clearTimeout(lp);lp=null;} }
        function resetFF(){ if(ff){v.playbackRate=1.0;ff=false;if(wasPaused)v.pause();} }
        function flushSeek(){ if(seekPending){v.currentTime=pendT;seekPending=false;} clearTimeout(seekTimer); }

        v.addEventListener('touchstart', function(e){
            if(e.touches.length!==1) return;
            sx = e.touches[0].clientX;
            st0 = v.currentTime || 0;
            wasPaused = v.paused;
            lp = setTimeout(function(){
                ff = true;
                v.playbackRate = FAST_RATE;
                if(wasPaused) v.play();
            }, LONG_PRESS_MS);
        }, {passive:true});

        v.addEventListener('touchmove', function(e){
            if(e.touches.length!==1) return;
            stopLong();
            var dx = e.touches[0].clientX - sx;
            if(Math.abs(dx) > 15){
                if(ff){v.playbackRate=1.0;ff=false;}
                e.preventDefault();
                var dur = v.duration || 1;
                // ★ 滑动倍率在这里 ↓
                var nt = st0 + (dx / (window.innerWidth * 2)) * dur;
                if(nt<0) nt=0; if(nt>dur) nt=dur;
                pendT = nt;
                //showTip(nt);
                if(!seekPending){
                    seekPending = true;
                    seekTimer = setTimeout(function(){ v.currentTime = pendT; seekPending = false; }, SEEK_THROTTLE);
                }
            }
        }, {passive:false});

        v.addEventListener('touchend', function(){
            stopLong();
            if(ff){ resetFF(); return; }
            flushSeek();
            hideTip();
        });
        v.addEventListener('touchcancel', function(){
            stopLong();
            if(ff){ resetFF(); return; }
            flushSeek();
            hideTip();
        });
    }

    function tryBind(){
        var v = document.querySelector('video');
        if(v){ bind(v); console.log('[手势注入] 已绑定'); }
        else setTimeout(tryBind, 300);
    }
    tryBind();
    console.log('[注入] 已启用');
})();

